-- ============================================================================
-- PrivateCloudDisk Notification Service - 邮件模板数据迁移
-- 从 Spring Boot platform-service 迁移完整 HTML 邮件模板
-- 替换原有的简化版模板，与业务服务保持完全一致
-- ============================================================================

-- 更新 welcome_email 模板（完整 HTML 来自 Spring Boot welcome-email.html）
UPDATE `pcd_notification_templates` SET
    `name` = '注册欢迎邮件',
    `title` = '欢迎使用私有云网盘',
    `body` = '欢迎加入私有云网盘，您的账号已成功创建。',
    `html_body` = '<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>欢迎使用私有云网盘</title>\n    <style>\n        body, table, td, a {\n            -webkit-text-size-adjust: 100%;\n            -ms-text-size-adjust: 100%;\n        }\n        table, td {\n            mso-table-lspace: 0pt;\n            mso-table-rspace: 0pt;\n        }\n        img {\n            -ms-interpolation-mode: bicubic;\n            border: 0;\n            outline: none;\n            text-decoration: none;\n        }\n        body {\n            margin: 0 !important;\n            padding: 0 !important;\n            width: 100% !important;\n            background-color: #f3f5f8;\n            font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\",\n            \"Hiragino Sans GB\", \"Microsoft YaHei\", Arial, sans-serif;\n        }\n        a {\n            color: #2563eb;\n            text-decoration: none;\n        }\n        @media screen and (max-width: 600px) {\n            .container {\n                width: 100% !important;\n            }\n            .outer-padding {\n                padding: 16px !important;\n            }\n            .mobile-padding {\n                padding-left: 22px !important;\n                padding-right: 22px !important;\n            }\n            .title {\n                font-size: 22px !important;\n            }\n            .button {\n                display: block !important;\n                width: 100% !important;\n                box-sizing: border-box !important;\n            }\n            .feature-column {\n                display: block !important;\n                width: 100% !important;\n                padding-right: 0 !important;\n                padding-left: 0 !important;\n                padding-bottom: 12px !important;\n            }\n        }\n    </style>\n</head>\n<body style=\"margin:0; padding:0; background-color:#f3f5f8;\">\n<div style=\"display:none; max-height:0; overflow:hidden; opacity:0; color:transparent; line-height:1px; font-size:1px;\">\n    欢迎加入私有云网盘，您的账号已成功创建。\n</div>\n<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#f3f5f8;\">\n    <tr>\n        <td align=\"center\" class=\"outer-padding\" style=\"padding:32px 12px;\">\n            <table role=\"presentation\" class=\"container\" width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                   style=\"width:600px; max-width:600px; background-color:#ffffff; border-radius:18px; overflow:hidden; border:1px solid #e5e7eb;\">\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:30px 36px 22px 36px; background-color:#ffffff; border-bottom:1px solid #eef0f4;\">\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                            <tr>\n                                <td valign=\"middle\" width=\"48\">\n                                    <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                                        <tr>\n                                            <td align=\"center\" valign=\"middle\"\n                                                style=\"width:44px; height:44px; background-color:#111827; border-radius:12px; color:#ffffff; font-size:15px; font-weight:700; letter-spacing:0.5px;\">\n                                                PCD\n                                            </td>\n                                        </tr>\n                                    </table>\n                                </td>\n                                <td valign=\"middle\" style=\"padding-left:12px;\">\n                                    <div style=\"font-size:16px; font-weight:700; color:#111827; line-height:1.4;\">\n                                        私有云网盘\n                                    </div>\n                                    <div style=\"font-size:12px; color:#6b7280; line-height:1.5;\">\n                                        Private Cloud Disk &middot; 安全可靠的文件存储服务\n                                    </div>\n                                </td>\n                            </tr>\n                        </table>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:38px 36px 18px 36px;\">\n                        <div style=\"display:inline-block; padding:6px 12px; background-color:#ecfdf5; border:1px solid #bbf7d0; border-radius:999px; color:#047857; font-size:13px; font-weight:600; line-height:1.2;\">\n                            注册成功\n                        </div>\n                        <h1 class=\"title\" style=\"margin:18px 0 12px 0; font-size:26px; line-height:1.35; color:#111827; font-weight:700;\">\n                            欢迎使用私有云网盘\n                        </h1>\n                        <p style=\"margin:0; font-size:14px; line-height:1.85; color:#4b5563;\">\n                            您好\n                            {{.Username}}，\n                            您的账号已成功创建。现在可以开始上传、管理和访问您的文件资源。\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:12px 36px 10px 36px;\">\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                               style=\"background-color:#f9fafb; border:1px solid #e5e7eb; border-radius:16px;\">\n                            <tr>\n                                <td style=\"padding:20px 20px 18px 20px;\">\n                                    <div style=\"font-size:14px; font-weight:700; color:#111827; margin-bottom:12px;\">\n                                        账号信息\n                                    </div>\n                                    <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                                        <tr>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#6b7280; width:90px;\">\n                                                账号邮箱\n                                            </td>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#111827; font-weight:600; word-break:break-all;\">\n                                                {{.Email}}\n                                            </td>\n                                        </tr>\n                                        <tr>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#6b7280; width:90px;\">\n                                                注册时间\n                                            </td>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#111827; font-weight:600;\">\n                                                {{.RegisterTime}}\n                                            </td>\n                                        </tr>\n                                        <tr>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#6b7280; width:90px;\">\n                                                账号状态\n                                            </td>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#047857; font-weight:700;\">\n                                                已启用\n                                            </td>\n                                        </tr>\n                                    </table>\n                                </td>\n                            </tr>\n                        </table>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" align=\"center\" style=\"padding:22px 36px 12px 36px;\">\n                        <a class=\"button\"\n                           href=\"{{.LoginUrl}}\"\n                           target=\"_blank\"\n                           style=\"display:inline-block; background-color:#111827; color:#ffffff; font-size:14px; font-weight:700; line-height:1.2; padding:15px 28px; border-radius:12px; text-align:center; text-decoration:none;\">\n                            进入私有云网盘\n                        </a>\n                        <div style=\"font-size:12px; color:#9ca3af; line-height:1.7; margin-top:12px;\">\n                            如果按钮无法打开，请复制登录地址到浏览器访问。\n                        </div>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:18px 36px 8px 36px;\">\n                        <div style=\"font-size:14px; font-weight:700; color:#111827; margin-bottom:12px;\">\n                            您可以开始使用\n                        </div>\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                            <tr>\n                                <td class=\"feature-column\" width=\"33.33%\" valign=\"top\" style=\"padding-right:8px;\">\n                                    <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                                           style=\"background-color:#ffffff; border:1px solid #e5e7eb; border-radius:14px;\">\n                                        <tr>\n                                            <td style=\"padding:16px 14px;\">\n                                                <div style=\"font-size:13px; font-weight:700; color:#111827; line-height:1.5;\">\n                                                    文件上传\n                                                </div>\n                                                <div style=\"font-size:12px; color:#6b7280; line-height:1.7; margin-top:5px;\">\n                                                    支持文件安全存储与统一管理\n                                                </div>\n                                            </td>\n                                        </tr>\n                                    </table>\n                                </td>\n                                <td class=\"feature-column\" width=\"33.33%\" valign=\"top\" style=\"padding-left:4px; padding-right:4px;\">\n                                    <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                                           style=\"background-color:#ffffff; border:1px solid #e5e7eb; border-radius:14px;\">\n                                        <tr>\n                                            <td style=\"padding:16px 14px;\">\n                                                <div style=\"font-size:13px; font-weight:700; color:#111827; line-height:1.5;\">\n                                                    快速访问\n                                                </div>\n                                                <div style=\"font-size:12px; color:#6b7280; line-height:1.7; margin-top:5px;\">\n                                                    在不同设备上访问您的资源\n                                                </div>\n                                            </td>\n                                        </tr>\n                                    </table>\n                                </td>\n                                <td class=\"feature-column\" width=\"33.33%\" valign=\"top\" style=\"padding-left:8px;\">\n                                    <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                                           style=\"background-color:#ffffff; border:1px solid #e5e7eb; border-radius:14px;\">\n                                        <tr>\n                                            <td style=\"padding:16px 14px;\">\n                                                <div style=\"font-size:13px; font-weight:700; color:#111827; line-height:1.5;\">\n                                                    安全保护\n                                                </div>\n                                                <div style=\"font-size:12px; color:#6b7280; line-height:1.7; margin-top:5px;\">\n                                                    保障账号与文件访问安全\n                                                </div>\n                                            </td>\n                                        </tr>\n                                    </table>\n                                </td>\n                            </tr>\n                        </table>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:18px 36px 30px 36px;\">\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                               style=\"background-color:#f8fafc; border:1px solid #e5e7eb; border-radius:14px;\">\n                            <tr>\n                                <td style=\"padding:16px 16px 14px 16px;\">\n                                    <div style=\"font-size:14px; font-weight:700; color:#111827; margin-bottom:8px;\">\n                                        安全建议\n                                    </div>\n                                    <div style=\"font-size:13px; line-height:1.8; color:#4b5563;\">\n                                        为了保护您的账号和文件安全，建议您妥善保管登录密码，不要与他人共享账号。\n                                        如果发现异常登录或文件访问行为，请及时联系管理员处理。\n                                    </div>\n                                </td>\n                            </tr>\n                        </table>\n                        <div style=\"height:1px; background-color:#eef0f4; margin:26px 0 18px 0;\"></div>\n                        <p style=\"margin:0; font-size:12px; line-height:1.8; color:#9ca3af; text-align:center;\">\n                            此邮件由系统自动发送，请勿直接回复。<br>\n                            如果您并未注册私有云网盘账号，请忽略此邮件或联系管理员。\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td style=\"padding:22px 36px; background-color:#f9fafb; border-top:1px solid #eef0f4; text-align:center;\">\n                        <div style=\"font-size:13px; color:#111827; font-weight:700; line-height:1.6;\">\n                            私有云网盘 Private Cloud Disk\n                        </div>\n                        <div style=\"font-size:11px; color:#9ca3af; line-height:1.8; margin-top:4px;\">\n                            Account Service Center\n                        </div>\n                        <div style=\"font-size:11px; color:#9ca3af; line-height:1.8; margin-top:8px;\">\n                            &copy; {{.CurrentYear}} Private Cloud Disk. All rights reserved.\n                        </div>\n                    </td>\n                </tr>\n            </table>\n        </td>\n    </tr>\n</table>\n</body>\n</html>',
    `variables_json` = '[{"name":"Username","type":"string","required":true,"desc":"用户名"},{"name":"Email","type":"string","required":true,"desc":"用户邮箱"},{"name":"RegisterTime","type":"string","required":true,"desc":"注册时间"},{"name":"LoginUrl","type":"string","required":true,"desc":"登录页面URL"},{"name":"CurrentYear","type":"string","required":true,"desc":"当前年份"}]'
WHERE `code` = 'welcome_email' AND `channel` = 'email' AND `lang` = 'zh-CN';

-- 更新 verification_email 模板（完整 HTML 来自 Spring Boot verification-email.html 亮色版）
UPDATE `pcd_notification_templates` SET
    `name` = '验证码邮件（亮色版）',
    `title` = '验证码 - 私有云网盘',
    `body` = '您正在进行安全验证操作，验证码：{{.VerificationCode}}，有效期 {{.ExpireMinutes}} 分钟。',
    `html_body` = '<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>验证码 - 私有云网盘</title>\n    <style>\n        body, table, td, a {\n            -webkit-text-size-adjust: 100%;\n            -ms-text-size-adjust: 100%;\n        }\n        table, td {\n            mso-table-lspace: 0pt;\n            mso-table-rspace: 0pt;\n        }\n        img {\n            -ms-interpolation-mode: bicubic;\n            border: 0;\n            outline: none;\n            text-decoration: none;\n        }\n        body {\n            margin: 0 !important;\n            padding: 0 !important;\n            width: 100% !important;\n            background-color: #ffffff;\n            font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\",\n            \"Hiragino Sans GB\", \"Microsoft YaHei\", Arial, sans-serif;\n        }\n        a {\n            color: #2563eb;\n            text-decoration: underline;\n        }\n        @media screen and (max-width: 600px) {\n            .container {\n                width: 100% !important;\n            }\n            .mobile-padding {\n                padding-left: 28px !important;\n                padding-right: 28px !important;\n            }\n            .code {\n                font-size: 48px !important;\n                letter-spacing: 3px !important;\n            }\n            .title {\n                font-size: 22px !important;\n            }\n        }\n    </style>\n</head>\n<body style=\"margin:0; padding:0; background-color:#ffffff;\">\n<div style=\"display:none; max-height:0; overflow:hidden; opacity:0; color:transparent; line-height:1px; font-size:1px;\">\n    您正在创建私有云网盘账号，请使用此验证码完成验证。\n</div>\n<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#ffffff;\">\n    <tr>\n        <td align=\"center\">\n            <table role=\"presentation\" class=\"container\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                   style=\"width:680px; max-width:680px; background-color:#ffffff;\">\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:48px 56px 24px 56px;\">\n                        <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                            <tr>\n                                <td valign=\"middle\">\n                                    <div style=\"width:42px; height:42px; border-radius:12px; background-color:#0f2d73; color:#ffffff; font-size:15px; font-weight:700; line-height:42px; text-align:center;\">\n                                        PCD\n                                    </div>\n                                </td>\n                                <td valign=\"middle\" style=\"padding-left:12px;\">\n                                    <div style=\"font-size:21px; line-height:1.2; color:#0f2d73; font-weight:700;\">\n                                        私有云网盘\n                                    </div>\n                                    <div style=\"font-size:13px; line-height:1.5; color:#64748b; margin-top:2px;\">\n                                        Private Cloud Disk\n                                    </div>\n                                </td>\n                            </tr>\n                        </table>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:18px 56px 0 56px;\">\n                        <p style=\"margin:0 0 26px 0; font-size:17px; line-height:1.8; color:#1f2937;\">\n                            您好\n                            <strong style=\"font-weight:700; color:#111827;\">{{.Username}}</strong>！\n                        </p>\n                        <p style=\"margin:0 0 30px 0; font-size:17px; line-height:1.8; color:#1f2937;\">\n                            感谢您使用私有云网盘。您正在进行\n                            <strong style=\"font-weight:700; color:#111827;\">{{.PurposeText}}</strong>\n                            操作，请使用以下一次性验证码完成验证：\n                        </p>\n                        <div class=\"code\"\n                             style=\"font-family:Consolas, Monaco, ''Courier New'', monospace; font-size:56px; line-height:1.2; letter-spacing:4px; font-weight:500; color:#000000; margin:0 0 30px 0;\">\n                            {{.VerificationCode}}\n                        </div>\n                        <p style=\"margin:0 0 28px 0; font-size:16px; line-height:1.9; color:#374151;\">\n                            请返回浏览器或客户端，在验证码输入框中输入此验证码。\n                            此验证码将在\n                            <strong style=\"color:#111827;\">{{.ExpireMinutes}}</strong>\n                            分钟后失效。\n                        </p>\n                        <p style=\"margin:0 0 30px 0; font-size:16px; line-height:1.9; color:#374151;\">\n                            如果您没有发起此操作，请忽略此邮件。为了保障账号安全，建议您及时检查账号登录记录或修改密码。\n                        </p>\n                        <p style=\"margin:0 0 8px 0; font-size:16px; line-height:1.8; color:#374151;\">\n                            谢谢您，\n                        </p>\n                        <p style=\"margin:0; font-size:16px; line-height:1.8; color:#374151;\">\n                            私有云网盘团队\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:38px 56px 0 56px;\">\n                        <div style=\"height:1px; background-color:#e5e7eb; line-height:1px; font-size:1px;\">&nbsp;</div>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:28px 56px 56px 56px;\">\n                        <p style=\"margin:0 0 16px 0; font-size:13px; line-height:1.8; color:#6b7280;\">\n                            此邮件发送至\n                            <span>{{.Email}}</span>，\n                            用于通知您的私有云网盘账号正在进行安全验证。\n                        </p>\n                        <p style=\"margin:0 0 8px 0; font-size:13px; line-height:1.8; color:#6b7280;\">\n                            &copy; {{.CurrentYear}} Private Cloud Disk. All rights reserved.\n                        </p>\n                        <p style=\"margin:0; font-size:13px; line-height:1.8; color:#6b7280;\">\n                            此邮件由系统自动发送，请勿直接回复。\n                            如需帮助，请联系\n                            <a href=\"mailto:{{.SupportEmail}}\">{{.SupportEmail}}</a>\n                        </p>\n                    </td>\n                </tr>\n            </table>\n        </td>\n    </tr>\n</table>\n</body>\n</html>',
    `variables_json` = '[{"name":"Username","type":"string","required":true,"desc":"用户名"},{"name":"PurposeText","type":"string","required":true,"desc":"操作用途文本"},{"name":"VerificationCode","type":"string","required":true,"desc":"验证码"},{"name":"ExpireMinutes","type":"int","required":true,"desc":"过期分钟数"},{"name":"Email","type":"string","required":true,"desc":"收件人邮箱"},{"name":"CurrentYear","type":"string","required":true,"desc":"当前年份"},{"name":"SupportEmail","type":"string","required":true,"desc":"支持邮箱地址"}]'
WHERE `code` = 'verification_email' AND `channel` = 'email' AND `lang` = 'zh-CN';

-- 新增 verification_email_dark 模板（暗色安全主题，来自 Spring Boot verification-email-dark.html）
INSERT INTO `pcd_notification_templates` (`code`, `name`, `channel`, `lang`, `title`, `body`, `html_body`, `variables_json`, `is_active`) VALUES
('verification_email_dark', '验证码邮件（暗色安全版）', 'email', 'zh-CN',
 '安全验证码 - 私有云网盘',
 '您正在进行敏感安全操作，验证码：{{.VerificationCode}}，有效期 {{.ExpireMinutes}} 分钟。',
 '<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>安全验证码 - 私有云网盘</title>\n    <style>\n        body, table, td, a {\n            -webkit-text-size-adjust: 100%;\n            -ms-text-size-adjust: 100%;\n        }\n        table, td {\n            mso-table-lspace: 0pt;\n            mso-table-rspace: 0pt;\n        }\n        img {\n            -ms-interpolation-mode: bicubic;\n            border: 0;\n            outline: none;\n            text-decoration: none;\n        }\n        body {\n            margin: 0 !important;\n            padding: 0 !important;\n            width: 100% !important;\n            background-color: #ffffff;\n            font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\",\n            \"Hiragino Sans GB\", \"Microsoft YaHei\", Arial, sans-serif;\n        }\n        a {\n            color: #60a5fa;\n            text-decoration: underline;\n        }\n        @media screen and (max-width: 600px) {\n            .container {\n                width: 100% !important;\n            }\n            .outer-padding {\n                padding: 24px 20px !important;\n            }\n            .card-padding {\n                padding-left: 24px !important;\n                padding-right: 24px !important;\n            }\n            .title {\n                font-size: 24px !important;\n            }\n            .code {\n                font-size: 42px !important;\n                letter-spacing: 3px !important;\n            }\n        }\n    </style>\n</head>\n<body style=\"margin:0; padding:0; background-color:#ffffff;\">\n<div style=\"display:none; max-height:0; overflow:hidden; opacity:0; color:transparent; line-height:1px; font-size:1px;\">\n    您正在进行敏感安全操作，请使用验证码确认身份。\n</div>\n<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#ffffff;\">\n    <tr>\n        <td align=\"center\" class=\"outer-padding\" style=\"padding:32px 24px;\">\n            <table role=\"presentation\" class=\"container\" width=\"720\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                   style=\"width:720px; max-width:720px;\">\n                <tr>\n                    <td style=\"background-color:#1f232a; border-radius:0;\">\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                            <tr>\n                                <td class=\"card-padding\" style=\"padding:36px 36px 16px 36px;\">\n                                    <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                                        <tr>\n                                            <td valign=\"middle\">\n                                                <div style=\"width:46px; height:46px; border-radius:50%; background-color:#ffffff; color:#0f2d73; font-size:15px; font-weight:800; line-height:46px; text-align:center;\">\n                                                    PCD\n                                                </div>\n                                            </td>\n                                            <td valign=\"middle\" style=\"padding-left:14px;\">\n                                                <div style=\"font-size:18px; line-height:1.3; color:#ffffff; font-weight:700;\">\n                                                    私有云网盘\n                                                </div>\n                                                <div style=\"font-size:12px; line-height:1.5; color:#9ca3af;\">\n                                                    Private Cloud Disk Security\n                                                </div>\n                                            </td>\n                                        </tr>\n                                    </table>\n                                </td>\n                            </tr>\n                        </table>\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                            <tr>\n                                <td class=\"card-padding\" style=\"padding:34px 36px 0 36px;\">\n                                    <h1 class=\"title\" style=\"margin:0 0 26px 0; font-size:30px; line-height:1.35; color:#d1d5db; font-weight:700;\">\n                                        {{.Username}}，您好！\n                                    </h1>\n                                    <p style=\"margin:0 0 24px 0; font-size:22px; line-height:1.55; color:#ffffff; font-weight:700;\">\n                                        要完成\n                                        {{.PurposeText}}\n                                        操作，请先确认您拥有此账号的访问权限。\n                                    </p>\n                                    <p style=\"margin:0 0 22px 0; font-size:15px; line-height:1.9; color:#d1d5db;\">\n                                        请在您的浏览器或客户端中输入以下一次性验证码：\n                                    </p>\n                                </td>\n                            </tr>\n                        </table>\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                            <tr>\n                                <td class=\"card-padding\" style=\"padding:0 36px 28px 36px;\">\n                                    <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                                           style=\"background-color:#15191f;\">\n                                        <tr>\n                                            <td align=\"center\" style=\"padding:30px 18px;\">\n                                                <div class=\"code\"\n                                                     style=\"font-family:Consolas, Monaco, ''Courier New'', monospace; font-size:48px; line-height:1.2; letter-spacing:5px; color:#4da3ff; font-weight:800;\">\n                                                    {{.VerificationCode}}\n                                                </div>\n                                            </td>\n                                        </tr>\n                                    </table>\n                                </td>\n                            </tr>\n                        </table>\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                            <tr>\n                                <td class=\"card-padding\" style=\"padding:0 36px 26px 36px;\">\n                                    <p style=\"margin:0; font-size:15px; line-height:1.9; color:#d1d5db;\">\n                                        此验证码将在\n                                        <strong style=\"color:#ffffff;\">{{.ExpireMinutes}}</strong>\n                                        分钟后失效。验证码仅用于当前操作，请不要转发或透露给任何人。\n                                    </p>\n                                </td>\n                            </tr>\n                        </table>\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                            <tr>\n                                <td class=\"card-padding\" style=\"padding:0 36px 34px 36px;\">\n                                    <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                                           style=\"background-color:#15191f;\">\n                                        <tr>\n                                            <td width=\"72\" align=\"center\" valign=\"middle\" style=\"padding:18px 0;\">\n                                                <div style=\"width:32px; height:32px; border-radius:50%; border:2px solid #d1d5db; color:#d1d5db; font-size:20px; line-height:30px; font-weight:700;\">\n                                                    i\n                                                </div>\n                                            </td>\n                                            <td valign=\"middle\" style=\"padding:18px 20px 18px 0;\">\n                                                <p style=\"margin:0; font-size:15px; line-height:1.8; color:#d1d5db;\">\n                                                    如果您没有尝试进行此操作，请立即修改密码，并检查账号安全设置。\n                                                </p>\n                                            </td>\n                                        </tr>\n                                    </table>\n                                </td>\n                            </tr>\n                        </table>\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                            <tr>\n                                <td class=\"card-padding\" style=\"padding:0 36px 42px 36px;\">\n                                    <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                                        <tr>\n                                            <td width=\"4\" style=\"background-color:#3b82f6; font-size:1px; line-height:1px;\">\n                                                &nbsp;\n                                            </td>\n                                            <td style=\"padding-left:28px;\">\n                                                <p style=\"margin:0 0 4px 0; font-size:15px; line-height:1.7; color:#d1d5db;\">\n                                                    祝您使用愉快，\n                                                </p>\n                                                <p style=\"margin:0; font-size:15px; line-height:1.7; color:#ffffff;\">\n                                                    私有云网盘安全团队\n                                                </p>\n                                            </td>\n                                        </tr>\n                                    </table>\n                                </td>\n                            </tr>\n                        </table>\n                    </td>\n                </tr>\n                <tr>\n                    <td style=\"padding:30px 18px 0 18px;\">\n                        <p style=\"margin:0 0 18px 0; font-size:15px; line-height:1.9; color:#111827;\">\n                            此通知已发送至与您的私有云网盘账号关联的电子邮件地址。\n                        </p>\n                        <p style=\"margin:0 0 18px 0; font-size:15px; line-height:1.9; color:#111827;\">\n                            这封电子邮件由系统自动生成，请勿回复。\n                            如果您需要额外帮助，请联系管理员或访问帮助中心。\n                        </p>\n                        <p style=\"margin:0; font-size:15px; line-height:1.9; color:#111827;\">\n                            <a href=\"{{.HelpUrl}}\" style=\"color:#111827; text-decoration:underline;\">帮助中心</a>\n                        </p>\n                    </td>\n                </tr>\n            </table>\n        </td>\n    </tr>\n</table>\n</body>\n</html>',
 '[{"name":"Username","type":"string","required":true,"desc":"用户名"},{"name":"PurposeText","type":"string","required":true,"desc":"操作用途文本"},{"name":"VerificationCode","type":"string","required":true,"desc":"验证码"},{"name":"ExpireMinutes","type":"int","required":true,"desc":"过期分钟数"},{"name":"HelpUrl","type":"string","required":true,"desc":"帮助中心URL"}]', 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`);

-- 同时更新英文版 welcome_email 模板
UPDATE `pcd_notification_templates` SET
    `name` = 'Welcome Email',
    `title` = 'Welcome to Private Cloud Disk',
    `body` = 'Welcome to Private Cloud Disk! Your account has been created successfully.',
    `html_body` = '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Welcome to Private Cloud Disk</title>\n    <style>\n        body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }\n        table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }\n        body {\n            margin: 0 !important; padding: 0 !important; width: 100% !important;\n            background-color: #f3f5f8;\n            font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Arial, sans-serif;\n        }\n        a { color: #2563eb; text-decoration: none; }\n        @media screen and (max-width: 600px) {\n            .container { width: 100% !important; }\n            .mobile-padding { padding-left: 22px !important; padding-right: 22px !important; }\n        }\n    </style>\n</head>\n<body style=\"margin:0; padding:0; background-color:#f3f5f8;\">\n<div style=\"display:none; max-height:0; overflow:hidden; opacity:0; color:transparent; line-height:1px; font-size:1px;\">\n    Welcome to Private Cloud Disk, your account has been created.\n</div>\n<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#f3f5f8;\">\n    <tr>\n        <td align=\"center\" style=\"padding:32px 12px;\">\n            <table role=\"presentation\" class=\"container\" width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                   style=\"width:600px; max-width:600px; background-color:#ffffff; border-radius:18px; overflow:hidden; border:1px solid #e5e7eb;\">\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:30px 36px 22px 36px; background-color:#ffffff; border-bottom:1px solid #eef0f4;\">\n                        <div style=\"font-size:16px; font-weight:700; color:#111827;\">Private Cloud Disk</div>\n                        <div style=\"font-size:12px; color:#6b7280;\">Secure File Storage Service</div>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:38px 36px 18px 36px;\">\n                        <div style=\"display:inline-block; padding:6px 12px; background-color:#ecfdf5; border:1px solid #bbf7d0; border-radius:999px; color:#047857; font-size:13px; font-weight:600;\">\n                            Registration Successful\n                        </div>\n                        <h1 style=\"margin:18px 0 12px 0; font-size:26px; line-height:1.35; color:#111827; font-weight:700;\">\n                            Welcome to Private Cloud Disk\n                        </h1>\n                        <p style=\"margin:0; font-size:14px; line-height:1.85; color:#4b5563;\">\n                            Hello {{.Username}},\n                            your account has been created successfully. You can now upload, manage, and access your files.\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" style=\"padding:12px 36px 10px 36px;\">\n                        <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n                               style=\"background-color:#f9fafb; border:1px solid #e5e7eb; border-radius:16px;\">\n                            <tr>\n                                <td style=\"padding:20px;\">\n                                    <div style=\"font-size:14px; font-weight:700; color:#111827; margin-bottom:12px;\">Account Information</div>\n                                    <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                                        <tr>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#6b7280; width:90px;\">Email</td>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#111827; font-weight:600;\">{{.Email}}</td>\n                                        </tr>\n                                        <tr>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#6b7280;\">Registered</td>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#111827; font-weight:600;\">{{.RegisterTime}}</td>\n                                        </tr>\n                                        <tr>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#6b7280;\">Status</td>\n                                            <td style=\"padding:8px 0; font-size:13px; color:#047857; font-weight:700;\">Active</td>\n                                        </tr>\n                                    </table>\n                                </td>\n                            </tr>\n                        </table>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"mobile-padding\" align=\"center\" style=\"padding:22px 36px 12px 36px;\">\n                        <a href=\"{{.LoginUrl}}\" target=\"_blank\"\n                           style=\"display:inline-block; background-color:#111827; color:#ffffff; font-size:14px; font-weight:700; padding:15px 28px; border-radius:12px; text-align:center; text-decoration:none;\">\n                            Go to Private Cloud Disk\n                        </a>\n                    </td>\n                </tr>\n                <tr>\n                    <td style=\"padding:22px 36px; background-color:#f9fafb; border-top:1px solid #eef0f4; text-align:center;\">\n                        <div style=\"font-size:13px; color:#111827; font-weight:700;\">Private Cloud Disk</div>\n                        <div style=\"font-size:11px; color:#9ca3af; margin-top:8px;\">&copy; {{.CurrentYear}} Private Cloud Disk. All rights reserved.</div>\n                    </td>\n                </tr>\n            </table>\n        </td>\n    </tr>\n</table>\n</body>\n</html>',
    `variables_json` = '[{"name":"Username","type":"string","required":true,"desc":"User display name"},{"name":"Email","type":"string","required":true,"desc":"User email"},{"name":"RegisterTime","type":"string","required":true,"desc":"Registration time"},{"name":"LoginUrl","type":"string","required":true,"desc":"Login page URL"},{"name":"CurrentYear","type":"string","required":true,"desc":"Current year"}]'
WHERE `code` = 'welcome_email' AND `channel` = 'email' AND `lang` = 'en-US';